    const handleCourtEdit = createHandleCourtEdit(ctx, rebuildItems);
    const root = document.createElement('div');
    root.style.cssText = STYLE_ROOT;

    // Instructions banner
    const banner = document.createElement('div');
    banner.style.cssText = 'padding: 8px 14px; background: rgba(33, 141, 141, 0.08); border-bottom: 1px solid var(--chc-border-primary); font-size: 13px; color: var(--chc-text-primary); font-family: sans-serif;';
    banner.innerHTML = '<strong>Multi-Row Creation:</strong> Double-click empty area, drag bottom handle to span courts, click ghost to confirm. Escape to cancel.';
    root.appendChild(banner);
    root.appendChild(statsBar.element);
    const mainRow = document.createElement('div');
    mainRow.style.cssText = STYLE_MAIN_ROW;
    const treePanel = buildCourtTreeWithEditIcons(venueInfos, visibleCourts, rebuildItems, handleVenueEdit, handleCourtEdit);
    const timelineContainer = document.createElement('div');
