    // Log panel for multi-row events
    const logPanel = document.createElement('div');
    logPanel.style.cssText = 'height: 80px; overflow-y: auto; padding: 6px 12px; border-top: 1px solid var(--chc-border-primary); font-family: monospace; font-size: 12px; background: var(--chc-bg-secondary); color: var(--chc-text-secondary);';
    logPanel.textContent = 'Event log:';
